import {samples,mergeRecords} from './core.js';
// UI depends on this repository contract. A future HTTP adapter can replace it.
const key='movex-marketing-v1';
export const initialEvents=[{id:'a',title:'스마트 물류 자동화 솔루션 소개',date:'2026-10-08',channel:'youtube',status:'업로드 완료'},{id:'b',title:'글로벌 물류 트렌드 인사이트',date:'2026-10-15',channel:'linkedin',status:'업로드 완료'},{id:'c',title:'현대무벡스 기술 현장 스케치',date:'2026-10-23',channel:'instagram',status:'검토 중'},{id:'d',title:'스마트 팩토리의 새로운 가능성',date:'2026-10-29',channel:'youtube',status:'제작 중'},{id:'e',title:'물류 자동화 기술 리포트',date:'2026-11-12',channel:'linkedin',status:'기획'}];
export class LocalRepository{constructor(){const raw=localStorage.getItem(key);if(raw){try{this.state=JSON.parse(raw);if(!Array.isArray(this.state.records)||!Array.isArray(this.state.events))throw Error();}catch{throw Error('저장된 데이터가 손상되었습니다. 브라우저 저장소를 확인하세요.');}}else this.state={records:samples(),events:initialEvents};}async listRecords(){return structuredClone(this.state.records);}async listEvents(){return structuredClone(this.state.events);}persist(next){localStorage.setItem(key,JSON.stringify(next));this.state=next;}async importRecords(rows){this.persist({...this.state,records:mergeRecords(this.state.records,rows)});}async saveEvent(event){this.persist({...this.state,events:this.state.events.filter(e=>e.id!==event.id).concat(event)});}async deleteEvent(id){this.persist({...this.state,events:this.state.events.filter(e=>e.id!==id)});}}
